/**************************************************************
 * A simple terrain shader with green and brown land,
 * plus blue water at lower altitudes.
 *
 * Feel free to modify to taste!
 **************************************************************/

// A small utility to hash a vec2 (for pseudo-randomness)
float hash21(vec2 p) {
    // A classic 2D hash function
    p = fract(p * 2345.6789);
    p += dot(p, p + 34.5678);
    return fract(p.x * p.y);
}

// 2D Noise function (value noise)
float noise2D(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    // Four corners in 2D of a tile
    float a = hash21(i + vec2(0.0, 0.0));
    float b = hash21(i + vec2(1.0, 0.0));
    float c = hash21(i + vec2(0.0, 1.0));
    float d = hash21(i + vec2(1.0, 1.0));

    // Smooth interpolation
    vec2 u = f * f * (3.0 - 2.0 * f);

    // Mix the four corners
    return mix(
        mix(a, b, u.x),
        mix(c, d, u.x),
        u.y
    );
}

// Fractal noise function for more interesting terrain
float fbm(vec2 p) {
    float result = 0.0;
    float amp = 0.5;
    float freq = 1.0;

    for(int i = 0; i < 5; i++) {
        result += noise2D(p * freq) * amp;
        freq *= 2.0;
        amp *= 0.5;
    }
    return result;
}

// Pseudocode for computeNormal:
// "p" is the position in noise space (like p = uv * 4.0 + vec2(t,t))
// "eps" is a small offset used to compute partial derivatives
vec3 computeNormal(vec2 p) {
    float eps = 0.0005;
    // Height at center
    float h = fbm(p);

    // Height at neighbor positions
    float hX = fbm(p + vec2(eps, 0.0));
    float hY = fbm(p + vec2(0.0, eps));

    // Compute partial derivatives
    // dx ~ slope in X direction, dy ~ slope in Y direction
    float dx = hX - h;
    float dy = hY - h;

    // Construct normal using derivative relationships
    // We treat "z" as up, so invert dx and dy accordingly
    vec3 normal = normalize(vec3(-dx, 1.0, -dy));
    return normal;
}

vec3 computeColor(vec2 fragCoord) {
    // Normalizing UV
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    float t = iTime * 0.05;

    // "uv" is normal screen uv in [-1..1]
    // We'll skew the y-axis based on the x-axis or vice-versa
    vec2 skewedUV = vec2(
        uv.x,
        uv.y * 3.2 - uv.x * 0.2   // tweak these constants
    );
    vec2 p = skewedUV * 4.0 + vec2(t, t);
    float height = fbm(p);

    //-------------------------------------------------
    // Get the normal for lighting calculations
    vec3 normal = computeNormal(p);

    // Let’s define a simple directional light:
    vec3 lightDir = normalize(vec3(0.3, 1.0, 0.4));
    // Or make it move around if you want:
    // vec3 lightDir = normalize(vec3(sin(iTime), 1.0, cos(iTime)));

    // Basic Lambertian shading
    float lambert = max(dot(normal, lightDir), 0.0);

    //-------------------------------------------------
    // Color from height
    vec3 baseColor;
    if (height < 0.3) {
        baseColor = mix(vec3(0.0, 0.2, 0.7), vec3(0.2, 0.7, 1.0), smoothstep(0.0, 0.3, height));
    } else {
        float factor = smoothstep(0.3, 0.7, height);
        vec3 green = vec3(0.1, 0.5, 0.1);
        vec3 brown = vec3(0.4, 0.2, 0.05);
        baseColor = mix(green, brown, factor);
    }

    // Final color = base color * diffuse shading
    vec3 color = baseColor * lambert;
    color += baseColor * 0.2;
    return color;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Offsets for 2×2 supersampling
    vec2 offsets[4] = vec2[](
        vec2(-0.25, -0.25),
        vec2( 0.25, -0.25),
        vec2(-0.25,  0.25),
        vec2( 0.25,  0.25)
    );

    vec3 colSum = vec3(0.0);
    for(int i = 0; i < 4; i++) {
        // Sample slightly shifted coordinates
        vec2 sampleCoord = fragCoord + offsets[i];
        // Collect the color from that sample
        colSum += computeColor(sampleCoord);
    }
    // Average out the samples
    vec3 finalColor = colSum / 4.0;
    fragColor = vec4(finalColor, 1.0);
}
